mapper.select:
WITH genes AS ( SELECT entrez_gene_id, hugo_gene_symbol, type FROM gene
WHERE entrez_gene_id IN #{item}
), samples AS ( SELECT sample_unique_id, sample_stable_id, patient_stable_id FROM sample_derived WHERE cancer_study_identifier = #{studyId}
AND sample_unique_id IN (#{sampleUniqueIds, typeHandler=org.apache.ibatis.type.ArrayTypeHandler})
AND internal_id IN ( SELECT sample_list_list.sample_id FROM sample_list_list INNER JOIN sample_list ON sample_list_list.list_id = sample_list.list_id WHERE sample_list.stable_id = #{sampleListId} )
) SELECT #{molecularProfileId} AS "molecularProfileId", s.sample_stable_id AS "sampleId", s.patient_stable_id AS "patientId", #{studyId} AS "studyId", g.entrez_gene_id AS "entrezGeneId",
g.entrez_gene_id AS "gene_entrezGeneId", g.hugo_gene_symbol AS "gene_hugoGeneSymbol", g.type AS "gene_type",
FROM genetic_alteration_derived d INNER JOIN genes g ON g.hugo_gene_symbol = d.hugo_gene_symbol INNER JOIN samples s ON s.sample_unique_id = d.sample_unique_id WHERE d.cancer_study_identifier = #{studyId} AND d.profile_type = #{profileType} AND d.hugo_gene_symbol IN (SELECT hugo_gene_symbol FROM genes) AND d.sample_unique_id IN (SELECT sample_unique_id FROM samples)
